<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api} from './api';
import {locale} from './i18n';
import world from './assets/world-land.svg';
const props=defineProps<{query:string;isAdmin:boolean;agents:Array<{id:number;name:string}>;timeline:Array<{time:string;events:number}>}>();
type Point={latitude:number;longitude:number};
type MapData={available:boolean;truncated:boolean;routes:Array<{agentId:number;agent:string;ip:string|null;events:number;location:(Point&{country:string;city:string|null})|null}>;targets:Array<Point&{agentId:number;label:string}>};
const data=ref<MapData|null>(null),error=ref(''),motion=ref(false),saving=ref(false);
const target=ref({agentId:0,label:'',latitude:0,longitude:0});
const th=computed(()=>locale.value==='th-TH');
const x=(p:Point)=>(p.longitude+180)*2,y=(p:Point)=>(90-p.latitude)*2;
const routes=computed(()=>data.value?.routes.flatMap(r=>{const t=data.value?.targets.find(t=>t.agentId===r.agentId);return r.location&&t?[{...r,start:r.location,end:t}]:[]})??[]);
const countries=computed(()=>{const counts=new Map<string,number>();for(const r of data.value?.routes??[])counts.set(r.location?.country??'Unknown',(counts.get(r.location?.country??'Unknown')??0)+r.events);return [...counts].sort((a,b)=>b[1]-a[1]).slice(0,10);});
const max=computed(()=>Math.max(1,...props.timeline.map(t=>t.events)));
let generation=0;
async function load(){const current=++generation;error.value='';try{const r=await api<MapData>(`/api/threats/map?${props.query}`);if(current===generation)data.value=r;}catch(e){if(current===generation){data.value=null;error.value=e instanceof Error?e.message:String(e);}}}
async function save(){saving.value=true;error.value='';try{await api(`/api/threats/locations/${target.value.agentId}`,{method:'PUT',body:JSON.stringify(target.value)});await load();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{saving.value=false;}}
watch(()=>props.query,load,{immediate:true});
</script>
<template><section class="panel threat-map"><header><h2>{{th?'แผนที่เหตุการณ์':'Event map'}}</h2><button class="secondary" @click="motion=!motion">{{motion?(th?'หยุดภาพเคลื่อนไหว':'Pause motion'):(th?'แสดงภาพเคลื่อนไหว':'Animate')}}</button></header><p>{{th?'ตำแหน่ง IP โดยประมาณ ไม่ใช่ตัวตนหรือสัญชาติผู้โจมตี เส้นเชื่อมไปเครื่องที่รายงาน Log (IDS คือ sensor) ไม่ใช่ packet สด':'IP locations are approximate, not attacker identity or nationality. Lines point to the reporting machine (IDS sensor), not necessarily the target. They are not live packets.'}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="data&&!data.available" class="notice">{{th?'ยังไม่มีฐานข้อมูล GeoIP: ติดตั้ง city.mmdb ตามคู่มือ แถวที่ไม่มีพิกัดยังดูได้ในตาราง':'GeoIP database unavailable: install city.mmdb using the guide. Unlocated events remain in the table.'}}</p>
<svg viewBox="0 0 720 360" role="img" :aria-label="th?'แผนที่ต้นทางและตำแหน่งเครื่องที่ตั้งไว้':'Source locations and configured server locations'" :class="{motion}"><image :href="world" width="720" height="360"/><g v-for="(r,i) in routes" :key="i"><path class="route" :d="`M${x(r.start)},${y(r.start)} Q${(x(r.start)+x(r.end))/2},${Math.min(y(r.start),y(r.end))-45} ${x(r.end)},${y(r.end)}`"/><circle :cx="x(r.start)" :cy="y(r.start)" r="3" fill="#f8a261"><title>{{r.ip}} → {{r.agent}} · {{r.events}}</title></circle></g><circle v-for="t in data?.targets" :key="t.agentId" :cx="x(t)" :cy="y(t)" r="4" fill="#41dbb6"><title>{{t.label}} #{{t.agentId}}</title></circle></svg>
<p>{{th?'เส้นที่แสดง':'Mapped routes'}}: {{routes.length}} / {{data?.routes.length??0}} · {{th?'100 คู่ IP/เครื่องอันดับแรก ที่ไม่มีพิกัดหรือไม่ได้ตั้งตำแหน่งเครื่องจะไม่วาดเส้น':'Top 100 IP/machine pairs; missing coordinates or server locations are not drawn'}}</p><p v-if="data?.truncated">{{th?'มีข้อมูลมากกว่าที่แสดง กรุณากรองเพิ่ม':'More routes exist; narrow the filters'}}</p>
<div class="map-charts"><div><h3>{{th?'ประเทศในคู่ IP/เครื่องที่แสดง':'Countries in displayed pairs'}}</h3><div v-for="[country,n] in countries" :key="country" class="country"><span>{{country==='Unknown'?(th?'ไม่ทราบ':'Unknown'):country}}</span><strong>{{n.toLocaleString(locale)}}</strong></div></div><div><h3>{{th?'เหตุการณ์รายชั่วโมง (UTC)':'Hourly events (UTC)'}}</h3><p>{{th?'168 ชั่วโมงที่มีข้อมูลล่าสุดในช่วงที่เลือก':'Latest 168 populated hours in the selected period'}}</p><div class="bars"><div v-for="bucket in timeline" :key="bucket.time" :style="{height:Math.max(2,bucket.events/max*100)+'%'}" :title="`${bucket.time}: ${bucket.events}`" /></div><small>{{timeline[0]?.time??'—'}} → {{timeline.at(-1)?.time??'—'}}</small></div></div>
<p class="attribution"><a href="https://db-ip.com" target="_blank" rel="noopener noreferrer">IP Geolocation by DB-IP</a> · Natural Earth (public domain)</p>
<details v-if="isAdmin"><summary>{{th?'ตั้งตำแหน่งเซิร์ฟเวอร์':'Set server location'}}</summary><form @submit.prevent="save"><label>{{th?'เครื่อง':'Machine'}}<select v-model.number="target.agentId" required><option :value="0" disabled>—</option><option v-for="a in agents" :key="a.id" :value="a.id">{{a.name}} #{{a.id}}</option></select></label><label>{{th?'ชื่อสถานที่':'Location label'}}<input v-model="target.label" maxlength="100" required></label><label>{{th?'ละติจูด':'Latitude'}}<input v-model.number="target.latitude" type="number" min="-90" max="90" step="any" required></label><label>{{th?'ลองจิจูด':'Longitude'}}<input v-model.number="target.longitude" type="number" min="-180" max="180" step="any" required></label><button class="primary" :disabled="saving||!target.agentId">{{th?'บันทึกตำแหน่ง':'Save location'}}</button></form></details>
</section></template>
<style scoped>
.threat-map{padding:20px;margin-bottom:20px}.threat-map header{display:flex;justify-content:space-between;align-items:center;gap:12px}.threat-map h2{font-size:19px}.threat-map p,.threat-map small{font-size:12px;color:#a6bbd2;line-height:1.7}.threat-map svg{width:100%;background:radial-gradient(ellipse at center,#102b40,#081320);border-radius:10px}.route{fill:none;stroke:#bb7bff;stroke-width:1.2;opacity:.7;stroke-dasharray:5 4}.motion .route{animation:flow 2s linear infinite}@keyframes flow{to{stroke-dashoffset:-36}}@media(prefers-reduced-motion:reduce){.motion .route{animation:none}}.map-charts{display:grid;grid-template-columns:1fr 2fr;gap:25px}.country{display:flex;justify-content:space-between;padding:5px}.bars{height:100px;display:flex;gap:2px;align-items:end}.bars>div{flex:1;background:#5db6c7;min-width:1px}.threat-map form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:15px}.notice{border-left:3px solid #e4b06b;padding-left:12px}summary{cursor:pointer}@media(max-width:650px){.map-charts,.threat-map form{grid-template-columns:1fr}}
</style>
